        series: [{
          type: 'bar',
          data: [
            barChartData[defaultSample]['Input'][defaultRnaIndex],
            barChartData[defaultSample]['Bio'][defaultRnaIndex]
          ]
        }],
        graphic: {
          type: 'text',
          left: 'center',
          top: 20,
          style: {
            text: `${defaultSample} - ${defaultTranscriptID}`,
            font: 'bold 14px sans-serif',
            fill: '#007bff',
            cursor: 'pointer'
          },
          onclick: () => {
            goToTranscriptPage(); // 点击文字时触发跟按钮一样的逻辑
          }
        }
      });
    });
    return {
      echartsRef,
      barChartRef,
      currentTranscriptID,
      goToTranscriptPage
    };
  }
};
</script>


